<script setup lang="ts">import AdminLayout from '@/Layouts/AdminLayout.vue';import {Head,router} from '@inertiajs/vue3';import {reactive,ref} from 'vue';const props=defineProps<{user:any,stats:any,history:any[]}>();const modal=ref(false);const form=reactive({action:'suspend',reason:'',expires_at:''});const submit=()=>router.post(route('admin.users.moderate',props.user.id),form,{onSuccess:()=>{modal.value=false;form.reason=''}});</script>
<template><Head :title="user.name"/><AdminLayout><div class="flex items-center justify-between"><div><h1 class="text-2xl font-bold">{{user.name}}</h1><p class="text-slate-500">{{user.email}}</p></div><button class="rounded bg-rose-600 px-4 py-2 text-white" @click="modal=true">Moderate user</button></div><div class="mt-7 grid gap-4 md:grid-cols-2"><section class="rounded-xl border bg-white p-5"><h2 class="font-semibold">Profile</h2><dl class="mt-4 space-y-2 text-sm"><div><dt class="text-slate-500">Role</dt><dd class="capitalize">{{user.role}}</dd></div><div><dt class="text-slate-500">Status</dt><dd class="capitalize">{{user.status}}</dd></div><div><dt class="text-slate-500">Joined</dt><dd>{{new Date(user.created_at).toLocaleString()}}</dd></div><div><dt class="text-slate-500">Last active</dt><dd>{{user.last_seen_at?new Date(user.last_seen_at).toLocaleString():'Never'}}</dd></div></dl></section><section class="rounded-xl border bg-white p-5"><h2 class="font-semibold">Statistics</h2><div class="mt-4 grid grid-cols-2 gap-3 text-sm"><div v-for="(value,label) in stats" :key="label" class="rounded bg-slate-50 p-3"><b class="block text-xl">{{value}}</b><span class="capitalize text-slate-500">{{label}}</span></div></div></section></div><section class="mt-6 rounded-xl border bg-white"><h2 class="border-b p-5 font-semibold">Moderation history</h2><p v-if="!history.length" class="p-5 text-sm text-slate-500">No actions recorded.</p><div v-for="item in history" :key="item.id" class="border-b p-4 text-sm"><b>{{item.action}}</b> by {{item.admin?.name}}<span v-if="item.reason"> — {{item.reason}}</span></div></section><div v-if="modal" class="fixed inset-0 z-30 grid place-items-center bg-black/40 p-4"><form class="w-full max-w-md rounded-xl bg-white p-6" @submit.prevent="submit"><h2 class="text-lg font-bold">Moderate {{user.name}}</h2><select v-model="form.action" class="mt-4 w-full rounded border p-2"><option value="suspend">Suspend</option><option value="unsuspend">Restore access</option><option value="ban">Ban</option><option value="unban">Unban</option></select><textarea v-model="form.reason" class="mt-3 w-full rounded border p-2" placeholder="Reason (required for suspend or ban)"/><input v-if="form.action==='suspend'" v-model="form.expires_at" type="datetime-local" class="mt-3 w-full rounded border p-2"><div class="mt-4 flex justify-end gap-2"><button type="button" class="rounded border px-4 py-2" @click="modal=false">Cancel</button><button class="rounded bg-rose-600 px-4 py-2 text-white">Confirm</button></div></form></div></AdminLayout></template>
